insert into public.startups (slug, cohort_year, display_number, name, category, accent, tags, description, tagline, segment, headline, paragraphs, features, socials, logo_url, team_image_url, sort_order)
values ('appono', '2026', '01', 'Appono', 'Tecnologia', 'amber', '{"pt":["Foodtech","Plataforma","Rotina alimentar"],"en":["Foodtech","Platform","Meal routine"]}'::jsonb, '{"pt":"Plataforma web que conecta clientes e restaurantes com rotina alimentar personalizada e pedidos antecipados.","en":"A web platform connecting customers and restaurants through personalized meal routines and advance ordering."}'::jsonb, '{"pt":"Foodtech · tecnologia para uma alimentação mais inteligente","en":"Foodtech · technology for smarter eating"}'::jsonb, '{"pt":"foodtech","en":"foodtech"}'::jsonb, '{"pt":{"text":"Alimentação que","emphasis":"entende você."},"en":{"text":"Food that","emphasis":"understands you."}}'::jsonb, '{"pt":["A Appono é uma plataforma digital que conecta pessoas e restaurantes em uma experiência de alimentação mais personalizada, previsível e eficiente. A solução transforma preferências, objetivos, orçamento e restrições alimentares em recomendações práticas para a rotina de cada cliente.","Com a Appono Rotina, o usuário planeja sua semana e encontra refeições e restaurantes alinhados ao seu perfil. Já o pedido antecipado permite reservar a refeição antes da chegada, reduzindo o tempo de espera e ajudando o restaurante a organizar melhor sua produção e seu fluxo de atendimento."],"en":["Appono is a digital platform connecting people and restaurants through a more personalized, predictable and efficient dining experience. The solution turns preferences, goals, budgets and dietary restrictions into practical recommendations for each customer’s routine.","With Appono Rotina, users plan their week and find meals and restaurants aligned with their profile. Advance ordering lets them reserve a meal before arriving, reducing waiting times and helping restaurants better organize production and service."]}'::jsonb, '{"pt":[{"title":"Rotina personalizada","description":"Alimentação mais adequada ao perfil do cliente."},{"title":"Pedido antecipado","description":"Menos espera e mais previsibilidade para restaurantes."},{"title":"Experiência integrada","description":"Conexão mais inteligente entre cliente e negócio."}],"en":[{"title":"Personalized routine","description":"Meals better suited to each customer’s profile."},{"title":"Advance ordering","description":"Less waiting and greater predictability for restaurants."},{"title":"Integrated experience","description":"A smarter connection between customers and businesses."}]}'::jsonb, '{"instagram":"https://www.instagram.com/appono.br/","linkedin":"https://linkedin.com/company/appono-br/","website":"#contato"}'::jsonb, 'appono/logo.png', 'appono/team.jpg', 1)
