values ('bixuco', '2026', '03', 'Bixuco', 'Tecnologia', 'lime', '{"pt":["Famílias","Produto conectado","Plataforma digital"],"en":["Families","Connected product","Digital platform"]}'::jsonb, '{"pt":"Startup brasileira que combina produto físico, tecnologia e plataforma digital para criar experiências voltadas ao contexto familiar.","en":"A Brazilian startup combining a physical product, technology and a digital platform to create experiences for family contexts."}'::jsonb, '{"pt":"Produto físico · plataforma digital · experiência familiar","en":"Physical product · digital platform · family experience"}'::jsonb, '{"pt":"famílias e tecnologia","en":"families and technology"}'::jsonb, '{"pt":{"text":"Produto físico com","emphasis":"experiência digital."},"en":{"text":"A physical product with","emphasis":"a digital experience."}}'::jsonb, '{"pt":["A Bixuco atua na interseção entre tecnologia, inovação e desenvolvimento de produtos, com a proposta de criar soluções voltadas ao contexto familiar. Seu principal produto em desenvolvimento é a pelúcia Bixuco, integrada a uma proposta tecnológica e a uma plataforma digital própria.","O projeto busca transformar um produto físico em uma experiência conectada ao ambiente digital. Para isso, trabalha em infraestrutura de front-end, back-end, integração de APIs e gerenciamento de dados, além de frentes estratégicas como finanças, comunicação, planejamento e identidade visual."],"en":["Bixuco works at the intersection of technology, innovation and product development, with the goal of creating solutions for family contexts. Its main product in development is the Bixuco plush toy, integrated with a technology proposal and its own digital platform.","The project aims to transform a physical product into an experience connected to the digital environment. To do so, it is developing front-end and back-end infrastructure, API integration and data management, as well as strategic areas such as finance, communication, planning and visual identity."]}'::jsonb, '{"pt":[{"title":"Pelúcia conectada","description":"Produto físico pensado para ampliar possibilidades de interação no ambiente familiar."},{"title":"Plataforma própria","description":"Base digital com front-end, back-end, APIs e dados para sustentar a experiência."},{"title":"Modelo escalável","description":"Proposta de valor para unir produto, tecnologia e experiência do usuário no mercado brasileiro."}],"en":[{"title":"Connected plush toy","description":"A physical product designed to expand interaction possibilities in family environments."},{"title":"Owned platform","description":"A digital base with front end, back end, APIs and data to support the experience."},{"title":"Scalable model","description":"A value proposition that combines product, technology and user experience for the Brazilian market."}]}'::jsonb, '{}'::jsonb, 'bixuco/logo.png', 'bixuco/team.png', 3)
