insert into public.startups (slug, cohort_year, display_number, name, category, accent, tags, description, tagline, segment, headline, paragraphs, features, socials, logo_url, team_image_url, sort_order)
values ('facos', '2026', '04', 'Faços', 'Tecnologia', 'facos', '{"pt":["Serviços locais","Conexão","Marketplace"],"en":["Local services","Connection","Marketplace"]}'::jsonb, '{"pt":"Startup que conecta prestadores de serviço aos clientes que buscam soluções para necessidades do dia a dia.","en":"A startup that connects service providers with customers looking for everyday solutions."}'::jsonb, '{"pt":"Serviços locais · conexão prática · comunidade","en":"Local services · practical connection · community"}'::jsonb, '{"pt":"serviços locais","en":"local services"}'::jsonb, '{"pt":{"text":"Serviços próximos","emphasis":"conectados a quem precisa."},"en":{"text":"Nearby services","emphasis":"connected to those who need them."}}'::jsonb, '{"pt":["A Faços é uma startup criada para aproximar prestadores de serviço de clientes que procuram apoio para demandas do dia a dia. A proposta é tornar mais simples encontrar, conhecer e entrar em contato com profissionais disponíveis.","Com foco em conexão local e praticidade, a solução organiza a ponte entre quem oferece um serviço e quem precisa contratá-lo. A marca usa uma identidade visual inspirada em localização, caminhos e colmeia para reforçar a ideia de rede, proximidade e colaboração."],"en":["Faços was created to bring service providers closer to customers looking for support with everyday needs. Its goal is to make it simpler to find, learn about and contact available professionals.","Focused on local connection and practicality, the solution builds a bridge between those offering a service and those who need to hire one. The brand identity draws from location, paths and honeycomb imagery to reinforce network, proximity and collaboration."]}'::jsonb, '{"pt":[{"title":"Conexão local","description":"Aproxima clientes de prestadores de serviço disponíveis na região."},{"title":"Busca prática","description":"Facilita encontrar ajuda para necessidades e tarefas do cotidiano."},{"title":"Rede de confiança","description":"Organiza contatos, serviços e oportunidades em uma experiência simples."}],"en":[{"title":"Local connection","description":"Brings customers closer to service providers available in their area."},{"title":"Practical search","description":"Makes it easier to find help for everyday needs and tasks."},{"title":"Trusted network","description":"Organizes contacts, services and opportunities in a simple experience."}]}'::jsonb, '{"instagram":"https://www.instagram.com/facos.oficial?stkn=MTU0cm5ibHpvejI1YQ==","github":"https://github.com/Pedro-Arruda-Az/Fa-os","website":"https://canva.link/gp4pe4iv9geyxka"}'::jsonb, 'facos/logo.svg', null, 4)
